"use client";

import { useEffect, useMemo, useState } from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { ArrowRight, BarChart3, CalendarDays, CircleHelp, Grid2X2, LayoutDashboard, LogOut, Menu, Shield, Trophy, Users, X, Zap } from "lucide-react";
import { browserSupabase } from "@dpl/supabase";
import { Logo } from "@dpl/ui";
import { POWER_UPS, SQUAD_BUDGET, SQUAD_SIZE, TIER_COUNTS, tierCountsAreValid, type Player, type Tier } from "@dpl/shared";

type ScorePoint = { night: number; gamePoints: number; overallPoints: number; wins: number; losses: number };
type ScoreMap = Record<string, ScorePoint[]>;
type WeeklySelections = Record<number, string[]>;
type PlayerWithMedia = Player & { photo?: string; teamLogo?: string };
type Leader = { id: string; teamName: string; displayName: string; weekPoints: number; overallPoints: number; position: number };

const colors = ["#c7ff21", "#62c8f5", "#f4a261", "#eb78b8", "#c19bf5", "#ff8076", "#f4c95d", "#70d6ff", "#b8f2e6"];
const nav = [["Dashboard", "/dashboard", LayoutDashboard], ["My team", "/dashboard/my-team", Grid2X2], ["Players", "/dashboard/players", Users], ["Fixtures", "/dashboard/fixtures", CalendarDays], ["Leaderboard", "/dashboard/leaderboard", Trophy], ["Rules", "/dashboard/rules", CircleHelp]] as const; const TOTAL_POWERUPS = POWER_UPS.filter((power) => power.id !== "diamond").length;

function mapPlayer(row: { id: string; name: string; team?: string; team_name?: string; category?: string; price?: number; cost?: number; form?: number; overall_points?: number; profile_picture?: string; avatar_url?: string; photo_url?: string; team_logo?: string; team_logo_url?: string; logo_url?: string }, index: number): PlayerWithMedia {
  const tier = (row.category || "DEV").toUpperCase() as Tier;
  return { id: row.id, name: row.name, initials: row.name.split(/\s+/).map((part) => part[0]).join("").slice(0, 2).toUpperCase(), club: row.team || row.team_name || "DPL club", tier: ["M1", "M2", "STAR", "CORE", "DEV"].includes(tier) ? tier : "DEV", price: Number(row.price ?? row.cost ?? 0), form: Number(row.form ?? row.overall_points ?? 0), color: colors[index % colors.length], photo: row.profile_picture || row.avatar_url || row.photo_url, teamLogo: row.team_logo || row.team_logo_url || row.logo_url };
}
function signed(value: number) { return value > 0 ? `+${value}` : String(value); }
function canonicalWeeklyPoints(values: number[]) { const finite = values.filter(Number.isFinite); if (!finite.length) return 0; return finite.reduce((best, value) => Math.abs(value) < Math.abs(best) ? value : best, finite[0]); }
function formatDeadline(value: string | null | undefined) { if (!value) return "Set by admin"; const date = new Date(value); if (Number.isNaN(date.getTime())) return "Set by admin"; const parts = new Intl.DateTimeFormat("en-GB", { weekday: "short", day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit", hour12: false }).formatToParts(date); const get = (type: string) => parts.find((part) => part.type === type)?.value || ""; return `${get("weekday")} ${get("day")} ${get("month")} ${get("hour")}:${get("minute")}`; }
function formatDeadlineRange(start: string | null | undefined, end: string | null | undefined) { const startLabel = formatDeadline(start); const endLabel = formatDeadline(end); return startLabel === "Set by admin" ? startLabel : endLabel === "Set by admin" ? startLabel : `${startLabel} → ${endLabel}`; }
function LoadingScreen() { return <div className="loading-screen" role="status" aria-live="polite"><div className="loading-logo"><Logo /></div><div className="loading-spinner" aria-hidden="true" /><p>Loading your DPL Fantasy team…</p></div>; }

function Sidebar({ open, setOpen, active, fullName, teamName, currentNight, deadline, onLogout, onEditTeamName }: { open: boolean; setOpen: (value: boolean) => void; active: string; fullName: string; teamName: string; currentNight: number; deadline: string; onLogout: () => void; onEditTeamName: () => void }) {
  return <><div className={`overlay ${open ? "show" : ""}`} onClick={() => setOpen(false)} /><aside className={`sidebar ${open ? "open" : ""}`}><div className="sidebar-top"><Link href="/" onClick={() => setOpen(false)}><Logo /></Link><button className="mobile-close" onClick={() => setOpen(false)}><X size={18} /></button></div><div className="league-label">Fantasy league<strong>Season 05 <span>/ Week {String(currentNight).padStart(2, "0")}</span></strong></div><nav>{nav.map(([label, href, Icon]) => <Link key={href} href={href} onClick={() => setOpen(false)} className={active === label ? "active" : ""}><Icon size={17} />{label}</Link>)}</nav><div className="lock-card"><div>Week {String(currentNight).padStart(2, "0")} lock <i /></div><strong>{deadline}</strong><p>Once locked, your team stays unchanged until the published deadline ends.</p></div><div className="account"><span>{(fullName || "Manager").slice(0, 2).toUpperCase()}</span><div><strong>{fullName || "Manager"}</strong><small>{teamName || "New manager"}</small><button className="account-edit" onClick={onEditTeamName} type="button">Edit team name</button></div><button className="logout-button" onClick={onLogout} title="Log out" aria-label="Log out"><LogOut size={15} /><span>Log out</span></button></div></aside></>;
}

function Court({ players, scores, captain, chooseSlot }: { players: PlayerWithMedia[]; scores: ScoreMap; captain: string; chooseSlot: (tier: Tier, slot: number) => void }) {
  return <div className="padel-court"><div className="court-lines" /><div className="court-net" />{(["M1", "M2", "STAR", "CORE", "DEV"] as Tier[]).map((tier) => <div className={`court-row row-${tier.toLowerCase()}`} key={tier}>{Array.from({ length: TIER_COUNTS[tier] }).map((_, slot) => { const player = players.filter((item) => item.tier === tier)[slot]; const playerScores = player ? scores[player.id] ?? [] : []; const scoreLabel = playerScores.length ? playerScores.sort((a, b) => a.night - b.night).map((score) => `N${score.night} ${signed(captain === player?.id ? score.gamePoints * 2 : score.gamePoints)}`).join(" · ") : "0"; return <button key={`${tier}-${slot}`} onClick={() => chooseSlot(tier, slot)} className={`court-player ${captain === player?.id ? "captain" : ""} ${!player ? "empty-slot" : ""}`}>{player ? <><b className="player-score">{scoreLabel}</b><span style={{ background: player.color }}>{player.photo ? <img src={player.photo} alt="" /> : player.initials}{captain === player.id && <em>♛</em>}</span><strong>{player.name.split(" ")[0]}</strong></> : <><span className="slot-plus">+</span><strong>Choose</strong><small>{tier}</small></>}</button>; })}</div>)}</div>;
}

function ScoreBreakdown({ players, scores, captain, selectedWeek, availableWeeks, onWeekChange }: { players: Player[]; scores: ScoreMap; captain: string; selectedWeek: number; availableWeeks: number[]; onWeekChange: (week: number) => void }) {
  return <section className="card score-board"><div className="row"><div><p className="eyebrow">Live points</p><h2>Week-by-week scoring</h2></div><span className="power-count">Updates after admin scores</span></div><div className="week-tabs" role="tablist" aria-label="Choose a game week">{availableWeeks.map((week) => <button type="button" role="tab" aria-selected={selectedWeek === week} className={selectedWeek === week ? "selected" : ""} key={week} onClick={() => onWeekChange(week)}>N{week}</button>)}</div><p className="history-note">Players selected for Night {selectedWeek} and the points they scored.</p><div className="score-lines">{players.length ? players.map((player) => { const score = (scores[player.id] ?? []).find((item) => item.night === selectedWeek); const raw = score?.gamePoints ?? 0; return <div className="score-line" key={player.id}><strong>{player.name}{""}</strong><span>{score ? `N${selectedWeek} : ${signed(raw)} pts${""}` : `N${selectedWeek} : 0 pts`}</span></div>; }) : <p className="admin-note">No selected players were recorded for this game week.</p>}</div></section>;
}

function PlayerDrawer({ tier, slot, players, current, select, remove, captain, close, locked, captainOnly = false }: { tier: Tier; slot: number; players: PlayerWithMedia[]; current: Player[]; select: (player: Player) => void; remove: (player: Player) => void; captain: (id: string) => void; close: () => void; locked: boolean; captainOnly?: boolean }) {
  return <><div className="drawer-backdrop" onClick={close} /><aside className="player-drawer"><div className="row"><div><p className="eyebrow">{captainOnly ? "Diamond captain" : `Position ${slot + 1} · Choose a player`}</p><h2>{captainOnly ? "Choose from your team" : `${tier} pool`}</h2></div><button onClick={close}>×</button></div>{(captainOnly ? players.filter((player) => current.some((item) => item.id === player.id)) : players.filter((player) => player.tier === tier)).map((player) => { const photo = (player as PlayerWithMedia).photo; const isSelected = current.some((item) => item.id === player.id); return <div className={`drawer-player ${isSelected ? "selected" : ""}`} key={player.id} role="button" tabIndex={0} onClick={() => captainOnly ? (captain(player.id), close()) : select(player)} onKeyDown={(event) => { if (event.key === "Enter") captainOnly ? (captain(player.id), close()) : select(player); }}>{photo ? <img src={photo} alt={`${player.name} profile`} /> : <span style={{ background: player.color }}>{player.initials}</span>}<strong>{player.name}<small>{player.club} · {tier}</small></strong><b>P{player.price.toLocaleString()} · {player.form ? `${player.form} pts` : "View player"}</b><i className="drawer-actions"><button type="button" onClick={(event) => { event.stopPropagation(); captain(player.id); close(); }}>Captain</button>{isSelected && !locked && <button type="button" onClick={(event) => { event.stopPropagation(); remove(player); close(); }}>Remove</button>}</i></div>; })}</aside></>;
}

function Stat({ label, value, sub, icon: Icon, highlight }: { label: string; value: string; sub: string; icon: typeof Users; highlight?: boolean }) { return <div className={`stat ${highlight ? "highlight" : ""}`}><span>{label}<Icon size={15} /></span><strong>{value}</strong><small>{sub}</small></div>; }
function Fixture({ home, away, homePlayers, awayPlayers, score, status, night }: { home: string; away: string; homePlayers: PlayerWithMedia[]; awayPlayers: PlayerWithMedia[]; score: string; status: string; night: number }) {
  const logoFor = (players: PlayerWithMedia[]) => players.find((player) => player.teamLogo)?.teamLogo;
  const initialsFor = (team: string) => team.split(/\s+/).map((part) => part[0]).join("").slice(0, 2).toUpperCase();
  const team = (name: string, players: PlayerWithMedia[]) => <div className="fixture-side"><span className="fixture-team-logo">{logoFor(players) ? <img src={logoFor(players)} alt="" /> : initialsFor(name)}</span><span><small>{name}</small><strong>{players.length ? players.map((player) => player.name).join(" & ") : "Players not listed"}</strong></span></div>;
  return <div className="fixture"><div className="fixture-match"><small className="fixture-week">● &nbsp;Week {String(night).padStart(2, "0")} · {status}</small>{team(home, homePlayers)}<em className="fixture-vs">vs</em>{team(away, awayPlayers)}</div><b>{score}</b></div>;
}

function TeamSetup({ name, setName, fullName, setFullName, save }: { name: string; setName: (value: string) => void; fullName: string; setFullName: (value: string) => void; save: () => void }) {
  const [step, setStep] = useState(name.trim() ? 2 : 1);
  return <div className="setup-backdrop"><div className="setup-card"><p className="eyebrow">Welcome to DPL Fantasy · Step {step} of 2</p><h2>{step === 1 ? "Name your fantasy team." : "Now add your full name."}</h2><p>{step === 1 ? "Your team name will appear first on the leaderboard." : "Your full name will appear underneath your team name so managers know who is behind the score."}</p>{step === 1 ? <><input autoFocus value={name} onChange={(event) => setName(event.target.value)} placeholder="e.g. Court Vision" /><button className="primary" onClick={() => setStep(2)} disabled={!name.trim()}>Continue <ArrowRight size={16} /></button></> : <><input autoFocus value={fullName} onChange={(event) => setFullName(event.target.value)} placeholder="e.g. Nabeel Abdulla" /><button className="primary" onClick={save} disabled={!fullName.trim()}>Save profile and build your team <ArrowRight size={16} /></button><button className="text-link setup-back" onClick={() => setStep(1)}>Back to team name</button></>}</div></div>;
}
function PageTitle({ eyebrow, title, description }: { eyebrow: string; title: string; description: string }) { return <div className="page-title"><p className="eyebrow">{eyebrow}</p><h1>{title}</h1><p>{description}</p></div>; }

function DashboardPage({ deadline, points, overallPoints, transfersRemaining, deadlineEnded, powerupsRemaining }: { deadline: string; points: number; overallPoints: number; transfersRemaining: number; deadlineEnded: boolean; powerupsRemaining: number }) {
  return <><PageTitle eyebrow="Dashboard" title="Your fantasy snapshot." description="Build from empty positions, lock your lineup, and follow every game week point." /><div className="stats"><Stat label="Power-ups remaining" value={`${powerupsRemaining} / ${TOTAL_POWERUPS}`} sub="One-time cards available" icon={Zap} /><Stat label="Week points" value={signed(points)} sub="Selected players" icon={Trophy} /><Stat label="Free transfers" value={`${transfersRemaining} / 2`} sub={deadlineEnded ? "Available now" : "Available after deadline"} icon={BarChart3} /><Stat label="Overall points" value={signed(overallPoints)} sub="Total across nights" icon={Trophy} highlight /></div><section className="card summary-card"><p className="eyebrow">Next deadline</p><h2>{deadline}</h2><p>Open <Link href="/dashboard/my-team">My team</Link> to build and lock your eight-player court.</p></section></>;
}

function PlayersPage({ pool, scores, currentNight, availableWeeks }: { pool: PlayerWithMedia[]; scores: ScoreMap; currentNight: number; availableWeeks: number[] }) { const [selectedWeek, setSelectedWeek] = useState(currentNight); useEffect(() => setSelectedWeek(currentNight), [currentNight]); const weeks = availableWeeks.length ? availableWeeks : [currentNight]; return <><PageTitle eyebrow="Players" title="The full player pool." description="Browse every DPL fantasy tier and review each player’s points for a selected game week." /><section className="card players-history"><div className="row"><div><p className="eyebrow">Weekly player scores</p><h2>Choose a game week</h2></div><span className="power-count">N{selectedWeek}</span></div><div className="week-tabs" role="tablist" aria-label="Choose a game week">{weeks.map((week) => <button type="button" role="tab" aria-selected={selectedWeek === week} className={selectedWeek === week ? "selected" : ""} key={week} onClick={() => setSelectedWeek(week)}>N{week}</button>)}</div><p className="history-note">Points scored in that game week, grouped by tier.</p></section><div className="tier-page">{(["M1", "M2", "STAR", "CORE", "DEV"] as Tier[]).map((tier) => <section className="card tier-block" key={tier}><div className="row"><div><p className="eyebrow">Tier</p><h2>{tier}</h2></div><strong className="lime">{pool.filter((player) => player.tier === tier).length} players</strong></div><div className="player-grid">{pool.filter((player) => player.tier === tier).map((player) => { const score = (scores[player.id] ?? []).find((item) => item.night === selectedWeek); return <div className="player-row" key={player.id}><span style={{ background: player.color }}>{player.photo ? <img src={player.photo} alt="" /> : player.initials}</span><strong>{player.name}<small>{player.club}</small></strong><div className="player-week-score"><b>N{selectedWeek} : {signed(score?.gamePoints ?? 0)} pts</b><small>game-week score</small></div><i>P{player.price.toLocaleString()}</i></div>; })}</div></section>)}</div></>; }
function FixturesPage({ currentNight }: { currentNight: number }) {
  const [fixtures, setFixtures] = useState<any[]>([]);
  const [players, setPlayers] = useState<PlayerWithMedia[]>([]);
  useEffect(() => { let cancelled = false; const load = async () => { const client = browserSupabase(); const [{ data: fixtureRows }, { data: playerRows }] = await Promise.all([client.from("fantasy_fixtures").select("id,home_team,away_team,home_score,away_score,status,night,played_at,home_player_1_id,home_player_2_id,away_player_1_id,away_player_2_id").eq("season", "Season 05").order("night", { ascending: false }), client.from("players").select("*").order("name")]); if (cancelled) return; setFixtures(fixtureRows ?? []); setPlayers((playerRows ?? []).map(mapPlayer)); }; void load(); return () => { cancelled = true; }; }, []);
  const byId = new Map(players.map((player) => [player.id, player]));
  return <><PageTitle eyebrow="Fixtures" title={`Week ${String(currentNight).padStart(2, "0")} fixtures.`} description="Published DPL Fantasy game-week fixtures, with the players who faced each other and their club logos." /><section className="card fixtures"><div className="fixture-grid">{fixtures.filter((fixture) => Number(fixture.night) === currentNight).map((fixture) => <Fixture key={fixture.id} home={fixture.home_team} away={fixture.away_team} homePlayers={[fixture.home_player_1_id, fixture.home_player_2_id].map((id: string | null) => id ? byId.get(id) : undefined).filter(Boolean) as PlayerWithMedia[]} awayPlayers={[fixture.away_player_1_id, fixture.away_player_2_id].map((id: string | null) => id ? byId.get(id) : undefined).filter(Boolean) as PlayerWithMedia[]} score={fixture.home_score !== null && fixture.away_score !== null ? `${fixture.home_score} — ${fixture.away_score}` : "Scheduled"} status={fixture.status} night={Number(fixture.night)} />)}</div>{!fixtures.filter((fixture) => Number(fixture.night) === currentNight).length && <p className="admin-note">No fixtures have been published for this week yet.</p>}</section></>;
}

function LeaderboardPage({ pool, currentNight, managerId }: { pool: Player[]; currentNight: number; managerId: string | null }) {
  const [leaders, setLeaders] = useState<Leader[]>([]);
  const [bought, setBought] = useState<{ player: Player; count: number }[]>([]);
  const [topScorers, setTopScorers] = useState<{ player: Player; points: number }[]>([]);
  const [captains, setCaptains] = useState<{ player: Player; count: number }[]>([]);
  const [showAll, setShowAll] = useState(false);
  useEffect(() => { let cancelled = false; const load = async () => { const client = browserSupabase(); const [{ data: managers }, { data: lineups }, { data: squads }, { data: managerScores }, { data: playerScores }, { data: fixturePoints }, { data: managerPlayerScores }, { data: fixturesForScoring }] = await Promise.all([client.from("fantasy_managers").select("id,team_name,display_name"), client.from("fantasy_manager_lineups").select("manager_id,player_id,period").eq("period", currentNight), client.from("fantasy_squads").select("manager_id,player_id,is_captain,season").eq("season", "Season 05"), client.from("fantasy_manager_gameweek_scores").select("manager_id,gameweek,points,overall_points").eq("season", "Season 05"), client.from("fantasy_player_scores").select("player_id,night,game_points").eq("season", "Season 05").eq("night", currentNight), client.from("fantasy_fixture_player_points").select("player_id,night,calculated_points").eq("season", "Season 05").eq("night", currentNight), client.from("fantasy_manager_player_scores").select("player_id,points").eq("season", "Season 05").eq("gameweek", currentNight), client.from("fantasy_fixtures").select("home_score,away_score,home_handicap,away_handicap,home_player_1_id,home_player_2_id,away_player_1_id,away_player_2_id").eq("season", "Season 05").eq("night", currentNight)]); if (cancelled) return;
      const managerRows = new Map<string, { weekPoints: number; overallPoints: number }>(); (managerScores ?? []).forEach((row: any) => { const existing = managerRows.get(row.manager_id) ?? { weekPoints: 0, overallPoints: 0 }; const gameweek = Number(row.gameweek); const points = Number(row.points ?? 0); existing.weekPoints += gameweek === currentNight ? points : 0; existing.overallPoints += points; managerRows.set(row.manager_id, existing); });
      setLeaders((managers ?? []).map((row: any) => { const points = managerRows.get(row.id) ?? { weekPoints: 0, overallPoints: 0 }; return { id: row.id, teamName: row.team_name || "Unnamed team", displayName: row.display_name || "Manager", ...points }; }).sort((a, b) => b.overallPoints - a.overallPoints || b.weekPoints - a.weekPoints || a.teamName.localeCompare(b.teamName)).map((leader, index) => ({ ...leader, position: index + 1 })));
      const managerSets = new Map<string, Set<string>>(); [...(lineups ?? []), ...(squads ?? []).map((row: any) => ({ manager_id: row.manager_id, player_id: row.player_id }))].forEach((row: any) => { const set = managerSets.get(row.player_id) ?? new Set<string>(); set.add(row.manager_id); managerSets.set(row.player_id, set); });
      setBought([...managerSets.entries()].map(([id, managersForPlayer]) => ({ player: pool.find((player) => player.id === id) as Player, count: managersForPlayer.size })).filter((row) => row.player).sort((a, b) => b.count - a.count || a.player.name.localeCompare(b.player.name)).slice(0, 5));
      const playerPoints = new Map<string, number>(); (playerScores ?? []).forEach((row: any) => playerPoints.set(row.player_id, Number(row.game_points ?? 0))); if (!playerScores?.length && fixturePoints?.length) { const fixtureTotals = new Map<string, number[]>(); (fixturePoints ?? []).forEach((row: any) => (fixtureTotals.get(row.player_id) ?? (fixtureTotals.set(row.player_id, []), fixtureTotals.get(row.player_id)!)).push(Number(row.calculated_points ?? 0))); fixtureTotals.forEach((values, playerId) => playerPoints.set(playerId, values.reduce((sum, value) => sum + value, 0))); } if (!playerScores?.length && !fixturePoints?.length && fixturesForScoring?.length) { (fixturesForScoring ?? []).forEach((fixture: any) => { const homeScore = Number(fixture.home_score); const awayScore = Number(fixture.away_score); const homeHandicap = Number(fixture.home_handicap ?? 0); const awayHandicap = Number(fixture.away_handicap ?? 0); if (![homeScore, awayScore, homeHandicap, awayHandicap].every(Number.isFinite)) return; const homePoints = homeScore - awayScore + awayHandicap - homeHandicap; [fixture.home_player_1_id, fixture.home_player_2_id].filter(Boolean).forEach((playerId: string) => playerPoints.set(playerId, (playerPoints.get(playerId) ?? 0) + homePoints)); [fixture.away_player_1_id, fixture.away_player_2_id].filter(Boolean).forEach((playerId: string) => playerPoints.set(playerId, (playerPoints.get(playerId) ?? 0) - homePoints)); }); } if (!playerScores?.length && !fixturePoints?.length && !fixturesForScoring?.length) { const candidatePoints = new Map<string, number[]>(); (managerPlayerScores ?? []).forEach((row: any) => (candidatePoints.get(row.player_id) ?? (candidatePoints.set(row.player_id, []), candidatePoints.get(row.player_id)!)).push(Number(row.points ?? 0))); candidatePoints.forEach((values, playerId) => playerPoints.set(playerId, canonicalWeeklyPoints(values))); } setTopScorers([...playerPoints.entries()].map(([id, points]) => ({ player: pool.find((player) => player.id === id) as Player, points })).filter((row) => row.player).sort((a, b) => b.points - a.points || a.player.name.localeCompare(b.player.name)).slice(0, 5));
      const captainCounts = new Map<string, Set<string>>(); (squads ?? []).filter((row: any) => row.is_captain).forEach((row: any) => { const set = captainCounts.get(row.player_id) ?? new Set<string>(); set.add(row.manager_id); captainCounts.set(row.player_id, set); }); setCaptains([...captainCounts.entries()].map(([id, managersForPlayer]) => ({ player: pool.find((player) => player.id === id) as Player, count: managersForPlayer.size })).filter((row) => row.player).sort((a, b) => b.count - a.count || a.player.name.localeCompare(b.player.name)).slice(0, 5));
    }; void load(); return () => { cancelled = true; }; }, [pool, currentNight]);
  const displayLeaders = showAll ? leaders : [...leaders.slice(0, 10), ...(managerId && leaders.length > 10 && !leaders.slice(0, 10).some((leader) => leader.id === managerId) ? leaders.filter((leader) => leader.id === managerId) : [])];
  const rankLabel = (position: number) => String(position);
  const highlight = (title: string, eyebrow: string, rows: Array<{ player: Player; value: string }>, empty: string) => <section className="card"><p className="eyebrow">{eyebrow}</p><h2>{title}</h2>{rows.length ? rows.map(({ player, value }) => <div className="highlight-row" key={player.id}><span style={{ background: player.color }}>{(player as PlayerWithMedia).photo ? <img src={(player as PlayerWithMedia).photo} alt="" /> : player.initials}</span><strong>{player.name}<small>{player.club}</small></strong><b>{value}</b></div>) : <p className="admin-note">{empty}</p>}</section>;
  return <><PageTitle eyebrow="Leaderboard" title="Every manager. Every point." description="Overall points determine the season ranking. Week points show only the selected game week, so both totals stay clearly in sync." /><section className="card leaderboard-full"><div className="leaderboard-heading"><div><p className="eyebrow">Season ranking</p><h2>Top managers</h2></div><span className="admin-note">{leaders.length} managers</span></div>{displayLeaders.map((leader, index) => <div className={`leader-row leaderboard-rank-${leader.position} ${leader.id === managerId ? "leader-row-current" : ""}`} key={leader.id}><b className="leader-position">{rankLabel(leader.position)}</b><span>{leader.teamName}<small>{leader.id === managerId ? "Your team · " : ""}{leader.displayName} · Week {signed(leader.weekPoints)}</small></span><strong>{signed(leader.overallPoints)}</strong></div>)}{leaders.length > 10 && <button className="show-more" onClick={() => setShowAll((value) => !value)}>{showAll ? "Show top 10" : "Show more"}</button>}{!leaders.length && <p className="admin-note">No managers have points yet.</p>}</section><div className="leaderboard-highlights">{highlight("Most bought players", "Market watch", bought.map(({ player, count }) => ({ player, value: `${count} teams` })), "No player selections have been published for this week yet.")}{highlight("Most points scored", "This week only", topScorers.map(({ player, points }) => ({ player, value: `${signed(points)} pts` })), "No fixture points have been published for this week yet.")}{highlight("Most captained players", "Captain watch", captains.map(({ player, count }) => ({ player, value: `${count} captains` })), "No captains have been selected for this week yet.")}</div></>;
}

function RulesPage() { return <><PageTitle eyebrow="Rules" title="How DPL Fantasy works." description="The essential rules for team selection, deadlines, transfers, and scoring." /><section className="card rules-summary"><p><strong>Start from scratch:</strong> every new manager sees all eight positions empty and must choose 1 M1, 1 M2, 2 Star, 2 Core, and 2 Dev players within P{SQUAD_BUDGET.toLocaleString()}.</p><p><strong>Lock your team:</strong> after confirming the starting team it cannot be edited while the admin deadline is active.</p><p><strong>Transfers:</strong> once the active window ends, exactly two free player transfers are available. The transfer counter does not unlock a full rebuild.</p><p><strong>Wildcard:</strong> the Wildcard power-up is the specific start-afresh option. It clears the current squad and lets you rebuild before locking again.</p><p><strong>Game-night points:</strong> admins publish wins, losses, game points, and overall points for each night. Selected players show that night’s points above their token and cumulative points below it.</p></section></>; }

function PowerControls({ captain, managerId, night, disabled, onMessage, onWildcard }: { captain: string; managerId: string | null; night: number; disabled: boolean; onMessage: (message: string) => void; onWildcard: () => void }) {
  const [used, setUsed] = useState<string[]>([]); const [selected, setSelected] = useState(""); const [saving, setSaving] = useState(false); const [confirming, setConfirming] = useState(false);
  useEffect(() => { if (!managerId) return; browserSupabase().from("fantasy_powerup_uses").select("powerup").eq("manager_id", managerId).eq("season", "Season 05").then(({ data }) => setUsed((data ?? []).map((row: any) => row.powerup))); }, [managerId]);
  const applyPowerup = async () => { if (!managerId || !selected || used.includes(selected) || disabled) return; setConfirming(false); setSaving(true); const { error } = await browserSupabase().rpc("use_fantasy_powerup", { p_powerup: selected, p_night: night, p_period: null, p_captain_player_id: captain || null }); setSaving(false); if (error) { onMessage(error.message.includes("already") ? "This power-up has already been used." : error.message); return; } setUsed((current) => [...current, selected]); if (selected === "wildcard") onWildcard(); onMessage((POWER_UPS.find((power) => power.id === selected)?.label || "Power-up") + " confirmed. " + (selected === "wildcard" ? "Your team is fresh and ready to rebuild." : "")); setSelected(""); };
  return <><section className="card power-panel"><div className="row"><div><p className="eyebrow">One-time power-up cards</p><h2>{disabled ? "Available after the active window" : "Power-ups available now"}</h2></div><span className="power-count">{3 - used.filter((power) => power !== "diamond").length} seasonal left</span></div><div className="power-cards">{POWER_UPS.filter((power) => power.id !== "diamond").map((power) => { const unavailable = used.includes(power.id); return <button key={power.id} disabled={unavailable || disabled} onClick={() => setSelected(power.id)} className={selected === power.id ? "active" : ""}><Zap size={16}/><strong>{power.label}</strong><small>{power.description}</small><b>{unavailable ? "Used this season" : disabled ? "Available after active window" : "Available once"}</b></button>; })}</div><button className="primary power-confirm" disabled={!selected || saving || disabled} onClick={() => setConfirming(true)}>{saving ? "Confirming…" : "Confirm power-up"}</button><p className="power-note">Power-ups are one-time uses and available after the active window ends.</p></section>{confirming && <ActionConfirmModal title="Use this power-up?" body="This is a one-time card. Confirming it will permanently mark it as used for the season." confirmLabel={saving ? "Saving…" : "Use power-up"} onCancel={() => setConfirming(false)} onConfirm={() => void applyPowerup()} />}</>;
}
function MessageModal({ message, onClose }: { message: string; onClose: () => void }) { return <div className="message-modal-backdrop" role="presentation" onClick={onClose}><section className="message-modal" role="dialog" aria-modal="true" aria-labelledby="message-modal-title" onClick={(event) => event.stopPropagation()}><button className="message-modal-close" onClick={onClose} aria-label="Close message">×</button><p className="eyebrow">DPL Fantasy</p><h2 id="message-modal-title">Notice</h2><p>{message}</p><button className="primary" onClick={onClose}>Okay</button></section></div>; }

function LockConfirmModal({ saving, onCancel, onConfirm }: { saving: boolean; onCancel: () => void; onConfirm: () => void }) { return <div className="lock-modal-backdrop" role="presentation"><section className="lock-modal" role="dialog" aria-modal="true" aria-labelledby="lock-modal-title"><p className="eyebrow">Final team confirmation</p><h2 id="lock-modal-title">Lock this team now?</h2><p>You will not be able to make changes until the admin lock window ends. Your selected players, Diamond captain, and budget will be saved.</p><div className="lock-modal-actions"><button className="text-link" onClick={onCancel} disabled={saving}>Go back</button><button className="primary" onClick={onConfirm} disabled={saving}>{saving ? "Saving team…" : "Yes, lock my team"}</button></div></section></div>; }
function TeamNameModal({ value, setValue, saving, onCancel, onSave }: { value: string; setValue: (value: string) => void; saving: boolean; onCancel: () => void; onSave: () => void }) { return <div className="lock-modal-backdrop" role="presentation" onClick={onCancel}><section className="lock-modal team-name-modal" role="dialog" aria-modal="true" aria-labelledby="team-name-modal-title" onClick={(event) => event.stopPropagation()}><p className="eyebrow">Account settings</p><h2 id="team-name-modal-title">Change team name</h2><p>This is the manager name shown on the leaderboard. Your players, points, and locked team will stay unchanged.</p><label className="team-name-field"><span>Team name</span><input autoFocus maxLength={40} value={value} onChange={(event) => setValue(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") onSave(); }} placeholder="e.g. Court Vision" /></label><div className="lock-modal-actions"><button className="text-link" onClick={onCancel} disabled={saving}>Cancel</button><button className="primary" onClick={onSave} disabled={saving || value.trim().length < 2}>{saving ? "Saving…" : "Save team name"}</button></div></section></div>; }
function ActionConfirmModal({ title, body, confirmLabel, onCancel, onConfirm }: { title: string; body: string; confirmLabel: string; onCancel: () => void; onConfirm: () => void }) { return <div className="lock-modal-backdrop" role="presentation"><section className="lock-modal" role="dialog" aria-modal="true" aria-labelledby="action-confirm-title"><p className="eyebrow">DPL Fantasy confirmation</p><h2 id="action-confirm-title">{title}</h2><p>{body}</p><div className="lock-modal-actions"><button className="text-link" onClick={onCancel}>Cancel</button><button className="primary" onClick={onConfirm}>{confirmLabel}</button></div></section></div>; }

